parameters.command:
python3 -c "
import os, glob
try:
    import pypdf
except ImportError:
    try:
        import PyPDF2 as pypdf
    except ImportError:
        pypdf = None

print('pypdf module:', pypdf)

if pypdf:
    pdf_files = glob.glob('company_files/**/*.pdf', recursive=True)
    for f in pdf_files:
        try:
            reader = pypdf.PdfReader(f)
            text = ''
            for page in reader.pages:
                text += page.extract_text() or ''
            for kw in ['cluster', 'preventive', 'push', 'spot-check', 'spot check', 'hvac', 'plumbing', 'electrical']:
                if kw in text.lower():
                    print(f'Match {kw} in {f}')
        except Exception as e:
            pass
"
